def is_generic_of(typ: Any, gen: Any) -> bool:
    if not is_generic(typ) or not hasattr(typ, '__origin__'):
        return False
    origin = typ.__origin__
    if origin is gen:
        return True
    # Handle cases where gen is a typing generic (e.g., typing.Dict)
    # and origin is the builtin (e.g., dict), or gen has an __origin__
    gen_origin = getattr(gen, '__origin__', None)
    if gen_origin is not None and origin is gen_origin:
        return True
    return False
